// 18-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            acc <= 24'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            acc <= 24'd0;
            acc <= acc + (2*(0 + 1) + 3) * xs[0];
            acc <= acc + (2*(1 + 1) + 3) * xs[1];
            acc <= acc + (2*(2 + 1) + 3) * xs[2];
            acc <= acc + (2*(3 + 1) + 3) * xs[3];
            acc <= acc + (2*(4 + 1) + 3) * xs[4];
            acc <= acc + (2*(5 + 1) + 3) * xs[5];
            acc <= acc + (2*(6 + 1) + 3) * xs[6];
            acc <= acc + (2*(7 + 1) + 3) * xs[7];
            acc <= acc + (2*(8 + 1) + 3) * xs[8];
            acc <= acc + (2*(9 + 1) + 3) * xs[9];
            acc <= acc + (2*(10 + 1) + 3) * xs[10];
            acc <= acc + (2*(11 + 1) + 3) * xs[11];
            acc <= acc + (2*(12 + 1) + 3) * xs[12];
            acc <= acc + (2*(13 + 1) + 3) * xs[13];
            acc <= acc + (2*(14 + 1) + 3) * xs[14];
            acc <= acc + (2*(15 + 1) + 3) * xs[15];
            acc <= acc + (2*(16 + 1) + 3) * xs[16];
            acc <= acc + (2*(17 + 1) + 3) * xs[17];
            y <= acc[15:0];
        end
    end
endmodule
